AR = {}

_TEXT = re.compile(r'>([^<>]+)<')
_ATTR = re.compile(r'((?:content|alt|placeholder|aria-label|title)=")([^"]*)(")')

def _tr(txt):
    raw = html.unescape(txt)
    key = raw.strip().strip("\u200e\u200f")
    if key in AR:
        lead = raw[:len(raw) - len(raw.lstrip())]; tail = raw[len(raw.rstrip()):]
        return html.escape(lead + AR[key] + tail, quote=False)  # LRM/RLM atılır, Arapça metin zaten RTL
    return txt

def arabize(doc):
    head, sep, rest = doc.partition("<body")
    parts = re.split(r'(<script[\s\S]*?</script>)', rest)
    rest = "".join(p if p.startswith("<script") else _TEXT.sub(lambda m: ">" + _tr(m.group(1)) + "<", p) for p in parts)
    doc = head + sep + rest
    doc = re.sub(r'<title>([^<]*)</title>', lambda m: "<title>" + _tr(m.group(1)) + "</title>", doc)
    def attr(m):
        v = html.unescape(m.group(2)).strip().strip("\u200e\u200f")
        return m.group(1) + html.escape(AR[v], quote=True) + m.group(3) if v in AR else m.group(0)
    return _ATTR.sub(attr, doc)

